"""A teacher finds another teacher's saved paper, previews/prints it and evaluates another section with the same ID."""
from pathlib import Path
exec(Path('tests/cbse-mcq-browser.py').read_text().split("\nwith fx['ns']['sync_playwright']() as p:")[0])
with fx['ns']['sync_playwright']() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context(viewport={'width':390,'height':850});ctx.add_init_script('window.__guest=true');ctx.route('https://www.gstatic.com/firebasejs/**',mcq_sdk);page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.route('**/api/staff-access',lambda route:mcq_api(page,route));page.goto('http://127.0.0.1:8000/cbse-mission.html#tab=mcq&mcqClass=X&mcq=paper');page.get_by_role('heading',name='Prepare a question paper',exact=True).wait_for()
 root['mcq']=page.evaluate("""async draft=>{const {contributeMCQ,createMCQPaper}=await import('./cbse-mcq-model.js');let bank={};for(const topic of ['Grammar','Poetry'])bank=contributeMCQ(bank,{requestId:'library_deposit_'+topic,subjectId:'english',topic,verified:true,questions:Array.from({length:10},()=>({stem:'Ready prepared question?',options:['One','Two','Three','Four'],answer:'B'}))},{id:'X:one',name:'Question Contributor'},draft,1).next;for(let i=0;i<22;i++)bank=createMCQPaper(bank,{requestId:'library_paper_'+i,questionIds:Object.keys(bank.questions)},{id:'X:two',name:'Paper Creator'},100+i).next;return bank;}""",D)
 page.get_by_role('button',name='Ready-made QPs · subject-wise',exact=True).click();page.get_by_role('button',name='Refresh ready papers',exact=True).click();library=page.locator('.mcq-ready-papers');library.locator('tbody tr').first.wait_for();assert library.locator('tbody tr').count()==20;assert 'Paper Creator' in library.locator('tbody tr').first.inner_text();assert 'Grammar · Poetry' in library.locator('tbody tr').first.inner_text();page.get_by_role('button',name='More papers',exact=True).click();library.locator('[data-paper-id=QPE001]').wait_for();assert library.locator('tbody tr').count()==2;library.locator('[name=mcq-paper-search]').fill('poetry');page.get_by_role('button',name='More papers',exact=True).wait_for();assert library.locator('tbody tr').count()==20;library.locator('[name=mcq-paper-search]').fill('QPE001');row=library.locator('[data-paper-id=QPE001]');row.wait_for();assert library.locator('tbody tr').count()==1;row.get_by_role('button',name='Open soft copy',exact=True).click();preview=library.locator('.mcq-library-preview');preview.locator('.mcq-question').first.wait_for();assert preview.locator('.mcq-question').count()==20;assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');assert 'Correct answer' not in preview.inner_text();assert 'Paper Creator' in preview.inner_text();assert len(root['mcq']['papers'])==22
 page.evaluate("""()=>{new MutationObserver(items=>{for(const item of items)for(const node of item.addedNodes)if(node.matches?.('.mcq-print-frame'))node.contentWindow.print=()=>window.__libraryPrint=node.contentDocument.body.innerHTML;}).observe(document.body,{childList:true});}""");preview.get_by_role('button',name='Print A4 / save PDF — no answers',exact=True).click();page.wait_for_function('!!window.__libraryPrint');printed=page.evaluate('window.__libraryPrint');assert 'QPE001' in printed;assert 'Correct answer' not in printed;preview.get_by_role('button',name='Use this paper for evaluation',exact=True).click();evaluation=page.locator('.mcq-evaluation-form');evaluation.wait_for();assert page.locator('[name=mcq-test-id]').input_value()=='QPE001';evaluation.locator('[name=mcq-section]').select_option('b');assert 'X-B' in evaluation.locator('[name=mcq-section] option:checked').inner_text();assert len(root['mcq']['papers'])==22;failed=page.evaluate("""async()=>{const {printMCQPaper}=await import('./cbse-mcq-print.js');const before=document.querySelectorAll('.mcq-print-frame').length;try{await printMCQPaper({id:'QPE001',subjectName:'Synthetic',count:10,questions:[{stem:'',imageOnly:true,image:'data:image/png;base64,AAAA',options:['A','B','C','D']}]});return 'unexpected print';}catch(e){return {message:e.message,clean:document.querySelectorAll('.mcq-print-frame').length===before};}}""");assert failed['clean'];assert 'could not load' in failed['message'];assert not errors,errors
 for width in [360,768,1440]:
  page.set_viewport_size({'width':width,'height':1000});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
 print('PASS shared QP creator/subject/frozen topics, full-library search/pagination, answer-free preview/print and other-section reuse without duplicate papers');b.close()
